package com.yuegang.zhihui.order.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.order.api.*;import java.math.*;import java.time.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.*;
public final class OrderService{private final JdbcTemplate jdbc;private final TransactionTemplate tx;public OrderService(DataSource d){jdbc=new JdbcTemplate(d);tx=new TransactionTemplate(new DataSourceTransactionManager(d));}public OrderView create(long user,CreateOrderRequest c){return tx.execute(s->{OrderView existing=findByRequest(user,c.requestId());if(existing!=null)return existing;String currency=null;BigDecimal total=BigDecimal.ZERO;for(var i:c.items()){if(currency==null)currency="CNY";total=total.add(i.unitPrice().multiply(BigDecimal.valueOf(i.quantity())));}long id=next();String no="YG"+Long.toUnsignedString(id);jdbc.update("INSERT INTO order_main(id,order_no,request_id,user_id,status,total_amount,currency,remark,expires_at) VALUES(?,?,?,?, 'PENDING_PAYMENT',?,?,?,DATE_ADD(NOW(6),INTERVAL 30 MINUTE))",id,no,c.requestId(),user,total,currency,c.remark());for(var i:c.items()){BigDecimal sub=i.unitPrice().multiply(BigDecimal.valueOf(i.quantity()));jdbc.update("INSERT INTO order_item(id,order_id,sku_id,sku_code,product_name,unit_price,quantity,subtotal,product_snapshot) VALUES(?,?,?,?,?,?,?,?,JSON_OBJECT('skuId',?,'skuCode',?,'name',?,'unitPrice',?))",next(),id,id(i.skuId()),i.skuCode(),i.productName(),i.unitPrice(),i.quantity(),sub,i.skuId(),i.skuCode(),i.productName(),i.unitPrice());}var a=c.address();jdbc.update("INSERT INTO order_address_snapshot(order_id,recipient_name,recipient_phone,country_code,province_code,province_name,city_name,district_name,address_detail,postal_code) VALUES(?,?,?,?,?,?,?,?,?,?)",id,a.recipientName(),a.recipientPhone(),a.countryCode(),a.provinceCode(),a.provinceName(),a.cityName(),a.districtName(),a.addressDetail(),a.postalCode());history(id,null,"PENDING_PAYMENT",null,"ORDER_CREATED");outbox(id,"ORDER_CREATED",UUID.randomUUID().toString());return get(user,Long.toString(id));});}public OrderView get(long user,String order){return jdbc.query("SELECT id,order_no,user_id,status,total_amount,currency,version,created_at FROM order_main WHERE id=? AND user_id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return view(r);},id(order),user);}public OrderView cancel(long user,String order,long version){return tx.execute(s->{long id=id(order);int n=jdbc.update("UPDATE order_main SET status='CANCELLED',cancelled_at=NOW(6),version=version+1 WHERE id=? AND user_id=? AND version=? AND status='PENDING_PAYMENT'",id,user,version);if(n!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);history(id,"PENDING_PAYMENT","CANCELLED",null,"USER_CANCELLED");outbox(id,"ORDER_CANCELLED",UUID.randomUUID().toString());return get(user,order);});}public void paymentSucceeded(String eventId,String orderId){tx.executeWithoutResult(s->{if(jdbc.update("INSERT IGNORE INTO order_inbox(event_id,event_type) VALUES(?,'WALLET_PAYMENT_SUCCEEDED')",eventId)==0)return;long id=id(orderId);int n=jdbc.update("UPDATE order_main SET status='PAID',paid_at=NOW(6),version=version+1 WHERE id=? AND status='PENDING_PAYMENT'",id);if(n==1){history(id,"PENDING_PAYMENT","PAID",eventId,"PAYMENT_SUCCEEDED");outbox(id,"ORDER_PAID",UUID.randomUUID().toString());}});}private OrderView findByRequest(long u,String r){return jdbc.query("SELECT id,order_no,user_id,status,total_amount,currency,version,created_at FROM order_main WHERE user_id=? AND request_id=?",x->x.next()?view(x):null,u,r);}private static OrderView view(java.sql.ResultSet r)throws java.sql.SQLException{return new OrderView(Long.toString(r.getLong(1)),r.getString(2),Long.toString(r.getLong(3)),OrderStatus.valueOf(r.getString(4)),r.getBigDecimal(5),r.getString(6),r.getLong(7),r.getTimestamp(8).toLocalDateTime().atOffset(ZoneOffset.UTC));}private void history(long o,String f,String t,String e,String reason){jdbc.update("INSERT INTO order_state_history(id,order_id,from_status,to_status,event_id,reason) VALUES(?,?,?,?,?,?)",next(),o,f,t,e,reason);}private void outbox(long o,String t,String e){jdbc.update("INSERT INTO order_outbox(id,aggregate_id,event_type,payload_json) VALUES(?,?,?,JSON_OBJECT('eventId',?,'orderId',?))",e,Long.toString(o),t,e,Long.toString(o));}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}private static long id(String s){try{long v=Long.parseLong(s);if(v<=0)throw new NumberFormatException();return v;}catch(NumberFormatException e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
